using Microsoft.Data.SqlClient;
using System.Data;
namespace LibraryManager.DAL;
public sealed class LibraryRepository
{
    private const string Cs = @"Server=localhost\SQLEXPRESS;Database=LibraryDB;Trusted_Connection=True;TrustServerCertificate=True;";
    private static SqlConnection Open(){var c=new SqlConnection(Cs);c.Open();return c;}
    private static DataTable Fill(string sql,Action<SqlCommand>? parameters=null){using var c=Open();using var d=new SqlDataAdapter(sql,c);parameters?.Invoke(d.SelectCommand!);var t=new DataTable();d.Fill(t);return t;}
    public DataTable Books()=>Fill("SELECT MaSach,TenSach,TheLoai,SoLuongCon FROM dbo.DauSach ORDER BY TenSach");
    public DataTable Readers()=>Fill("SELECT MaDocGia,HoTen,Email,NgayHetHanThe FROM dbo.DocGia ORDER BY HoTen");
    public DataTable BookChoices()=>Fill("SELECT MaSach,TenSach,TheLoai,SoLuongCon FROM dbo.DauSach WHERE SoLuongCon>0 ORDER BY TenSach");
    public DataTable Loans(int readerId,string status)=>Fill("SELECT p.MaPhieu,d.HoTen,p.NgayMuon,p.HanTra,p.TrangThai,STRING_AGG(s.TenSach,N', ') AS Sach FROM dbo.PhieuMuon p JOIN dbo.DocGia d ON d.MaDocGia=p.MaDocGia JOIN dbo.ChiTietMuon c ON c.MaPhieu=p.MaPhieu JOIN dbo.DauSach s ON s.MaSach=c.MaSach WHERE (@r=0 OR p.MaDocGia=@r) AND (@s=N'Tất cả' OR p.TrangThai=@s) GROUP BY p.MaPhieu,d.HoTen,p.NgayMuon,p.HanTra,p.TrangThai ORDER BY p.NgayMuon DESC",x=>{x.Parameters.Add("@r",SqlDbType.Int).Value=readerId;x.Parameters.Add("@s",SqlDbType.NVarChar,50).Value=status;});
    public DataTable Overdue(){using var c=Open();using var x=new SqlCommand("SELECT p.MaPhieu,d.HoTen,s.TenSach,p.NgayMuon,p.HanTra,DATEDIFF(day,p.HanTra,GETDATE()) AS SoNgayQuaHan,p.TrangThai FROM dbo.PhieuMuon p JOIN dbo.DocGia d ON d.MaDocGia=p.MaDocGia JOIN dbo.ChiTietMuon ct ON ct.MaPhieu=p.MaPhieu JOIN dbo.DauSach s ON s.MaSach=ct.MaSach WHERE p.HanTra<GETDATE() AND p.TrangThai<>N'Đã trả' ORDER BY p.HanTra",c);using var r=x.ExecuteReader();var t=new DataTable();t.Load(r);return t;}
    public DataTable GenreStats()=>Fill("SELECT s.TheLoai,SUM(c.SoLuong) AS LuotMuon FROM dbo.ChiTietMuon c JOIN dbo.DauSach s ON s.MaSach=c.MaSach GROUP BY s.TheLoai ORDER BY LuotMuon DESC");
    public void SaveBook(int? id,string title,string genre,int stock){using var c=Open();using var x=new SqlCommand(id is null?"INSERT dbo.DauSach(TenSach,TheLoai,SoLuongCon) VALUES(@t,@g,@n)":"UPDATE dbo.DauSach SET TenSach=@t,TheLoai=@g,SoLuongCon=@n WHERE MaSach=@id",c);x.Parameters.Add("@t",SqlDbType.NVarChar,200).Value=title;x.Parameters.Add("@g",SqlDbType.NVarChar,50).Value=genre;x.Parameters.Add("@n",SqlDbType.Int).Value=stock;if(id!=null)x.Parameters.Add("@id",SqlDbType.Int).Value=id;x.ExecuteNonQuery();}
    public void DeleteBook(int id){using var c=Open();using var x=new SqlCommand("DELETE dbo.DauSach WHERE MaSach=@id AND NOT EXISTS(SELECT 1 FROM dbo.ChiTietMuon WHERE MaSach=@id)",c);x.Parameters.Add("@id",SqlDbType.Int).Value=id;if(x.ExecuteNonQuery()==0)throw new InvalidOperationException("Không thể xóa sách đang có lịch sử mượn.");}
    public void SaveReader(int? id,string name,string email,DateTime expires){using var c=Open();using var x=new SqlCommand(id is null?"INSERT dbo.DocGia(HoTen,Email,NgayHetHanThe) VALUES(@n,@e,@x)":"UPDATE dbo.DocGia SET HoTen=@n,Email=@e,NgayHetHanThe=@x WHERE MaDocGia=@id",c);x.Parameters.Add("@n",SqlDbType.NVarChar,100).Value=name;x.Parameters.Add("@e",SqlDbType.VarChar,100).Value=email;x.Parameters.Add("@x",SqlDbType.DateTime).Value=expires.Date;if(id!=null)x.Parameters.Add("@id",SqlDbType.Int).Value=id;x.ExecuteNonQuery();}
    public void DeleteReader(int id){using var c=Open();using var x=new SqlCommand("DELETE dbo.DocGia WHERE MaDocGia=@id AND NOT EXISTS(SELECT 1 FROM dbo.PhieuMuon WHERE MaDocGia=@id)",c);x.Parameters.Add("@id",SqlDbType.Int).Value=id;if(x.ExecuteNonQuery()==0)throw new InvalidOperationException("Không thể xóa độc giả đã có phiếu mượn.");}
    public void Borrow(int readerId,int bookId,int quantity,int days){using var c=Open();using var tx=c.BeginTransaction();try{using(var valid=new SqlCommand("SELECT COUNT(*) FROM dbo.DocGia WHERE MaDocGia=@r AND NgayHetHanThe>=GETDATE()",c,tx)){valid.Parameters.Add("@r",SqlDbType.Int).Value=readerId;if(Convert.ToInt32(valid.ExecuteScalar())==0)throw new InvalidOperationException("Thẻ độc giả đã hết hạn hoặc không tồn tại.");}using(var stock=new SqlCommand("UPDATE dbo.DauSach SET SoLuongCon=SoLuongCon-@q WHERE MaSach=@b AND SoLuongCon>=@q",c,tx)){stock.Parameters.Add("@q",SqlDbType.Int).Value=quantity;stock.Parameters.Add("@b",SqlDbType.Int).Value=bookId;if(stock.ExecuteNonQuery()!=1)throw new InvalidOperationException("Số lượng sách còn không đủ.");}int loanId;using(var ins=new SqlCommand("INSERT dbo.PhieuMuon(MaDocGia,HanTra,TrangThai) VALUES(@r,DATEADD(day,@days,GETDATE()),N'Đang mượn'); SELECT CAST(SCOPE_IDENTITY() AS int)",c,tx)){ins.Parameters.Add("@r",SqlDbType.Int).Value=readerId;ins.Parameters.Add("@days",SqlDbType.Int).Value=days;loanId=Convert.ToInt32(ins.ExecuteScalar());}using(var detail=new SqlCommand("INSERT dbo.ChiTietMuon(MaPhieu,MaSach,SoLuong) VALUES(@p,@b,@q)",c,tx)){detail.Parameters.Add("@p",SqlDbType.Int).Value=loanId;detail.Parameters.Add("@b",SqlDbType.Int).Value=bookId;detail.Parameters.Add("@q",SqlDbType.Int).Value=quantity;detail.ExecuteNonQuery();}tx.Commit();}catch{tx.Rollback();throw;}}
    public void Return(int loanId){using var c=Open();using var tx=c.BeginTransaction();try{using var update=new SqlCommand("UPDATE dbo.PhieuMuon SET TrangThai=N'Đã trả' WHERE MaPhieu=@p AND TrangThai<>N'Đã trả'",c,tx);update.Parameters.Add("@p",SqlDbType.Int).Value=loanId;if(update.ExecuteNonQuery()==0)throw new InvalidOperationException("Phiếu không tồn tại hoặc đã được trả.");using var stock=new SqlCommand("UPDATE s SET s.SoLuongCon=s.SoLuongCon+c.SoLuong FROM dbo.DauSach s JOIN dbo.ChiTietMuon c ON c.MaSach=s.MaSach WHERE c.MaPhieu=@p",c,tx);stock.Parameters.Add("@p",SqlDbType.Int).Value=loanId;stock.ExecuteNonQuery();tx.Commit();}catch{tx.Rollback();throw;}}
    public int Scalar(string sql){using var c=Open();using var x=new SqlCommand(sql,c);return Convert.ToInt32(x.ExecuteScalar()??0);}
}
